package com.bonbio.controller;
import com.bonbio.dto.Dtos.*; import com.bonbio.service.CategorieService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/categories") public class CategorieController {private final CategorieService s; public CategorieController(CategorieService s){this.s=s;} @GetMapping public List<CategorieResponse> all(){return s.all();} @GetMapping({"/{id}/produits","/{id}/produit"}) public List<ProduitResponse> products(@PathVariable Long id){return s.products(id);} @GetMapping("/{id}") public CategorieResponse one(@PathVariable Long id){return s.one(id);} @PostMapping public CategorieResponse add(@Valid @RequestBody CategorieRequest r){return s.save(null,r);} @PutMapping("/{id}") public CategorieResponse edit(@PathVariable Long id,@Valid @RequestBody CategorieRequest r){return s.save(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} }
